    bod2501: true,
    exclusionType: "AllowedForwardingDomains",
    notes: ["Automatic forwarding MAY be enabled with specific, agency-approved domains. There may be cases where an external domain is operationally needed and has an acceptable degree of risk, e.g., a domain controlled by the same agency that hasn't been added as an accepted domain in M365."],
    nistMapping: ["AC-4"],
